1	/* ===== Lái xe: public/car/vf3.glb (sinh bằng scripts/car/convert.py) — đọc phần JSON của GLB, không cần three ===== */
2	import { test } from 'node:test';
3	import assert from 'node:assert/strict';
4	import { readFileSync, existsSync, statSync } from 'node:fs';
5	import { fileURLToPath } from 'node:url';
6	import { join, dirname } from 'node:path';
7	
8	const DIR = join(dirname(fileURLToPath(import.meta.url)), '../../public/car');
9	const FILE = join(DIR, 'vf3.glb');
10	const MAX_BYTES = 1_500_000, MAX_TRIS = 45_000;
11	type Vec = [number, number, number];
12	
13	function glbJson(file: string): any {
14	  const b = readFileSync(file);
15	  assert.equal(b.readUInt32LE(0), 0x46546c67, 'không phải GLB');            // 'glTF'
16	  const len = b.readUInt32LE(12);
17	  assert.equal(b.readUInt32LE(16), 0x4e4f534a, 'chunk đầu không phải JSON'); // 'JSON'
18	  return JSON.parse(b.subarray(20, 20 + len).toString('utf8'));
19	}
20	
21	/* Ma trận 4x4 cột-chính của một nút (matrix hoặc TRS) */
22	function nodeMat(n: any): number[] {
23	  if (n.matrix) return n.matrix.slice();
24	  const [x, y, z, w] = n.rotation ?? [0, 0, 0, 1], [sx, sy, sz] = n.scale ?? [1, 1, 1], [tx, ty, tz] = n.translation ?? [0, 0, 0];
25	  return [
26	    (1 - 2 * (y * y + z * z)) * sx, (2 * (x * y + z * w)) * sx, (2 * (x * z - y * w)) * sx, 0,
27	    (2 * (x * y - z * w)) * sy, (1 - 2 * (x * x + z * z)) * sy, (2 * (y * z + x * w)) * sy, 0,
28	    (2 * (x * z + y * w)) * sz, (2 * (y * z - x * w)) * sz, (1 - 2 * (x * x + y * y)) * sz, 0,
29	    tx, ty, tz, 1];
30	}
31	const mul = (a: number[], b: number[]): number[] => { const o = new Array(16).fill(0); for (let c = 0; c < 4; c++) for (let r = 0; r < 4; r++) for (let k = 0; k < 4; k++) o[c * 4 + r] += a[k * 4 + r] * b[c * 4 + k]; return o; };
32	const apply = (m: number[], p: Vec): Vec => [m[0] * p[0] + m[4] * p[1] + m[8] * p[2] + m[12], m[1] * p[0] + m[5] * p[1] + m[9] * p[2] + m[13], m[2] * p[0] + m[6] * p[1] + m[10] * p[2] + m[14]];
33	
34	/* Mọi nút có lưới -> hộp bao thế giới của từng primitive */
35	function worldBoxes(j: any): { node: string; mat: string; tris: number; min: Vec; max: Vec }[] {
36	  const out: any[] = [];
37	  const parent = new Map<number, number>();
38	  j.nodes.forEach((n: any, i: number) => (n.children ?? []).forEach((c: number) => parent.set(c, i)));
39	  const world = (i: number): number[] => { const m = nodeMat(j.nodes[i]); return parent.has(i) ? mul(world(parent.get(i)!), m) : m; };
40	  j.nodes.forEach((n: any, i: number) => {
41	    if (n.mesh === undefined) return;
42	    const W = world(i);
43	    for (const p of j.meshes[n.mesh].primitives) {
44	      const a = j.accessors[p.attributes.POSITION];
45	      const mn = [Infinity, Infinity, Infinity], mx = [-Infinity, -Infinity, -Infinity];
46	      for (let c = 0; c < 8; c++) {
47	        const q = apply(W, [c & 1 ? a.max[0] : a.min[0], c & 2 ? a.max[1] : a.min[1], c & 4 ? a.max[2] : a.min[2]]);
48	        for (let d = 0; d < 3; d++) { mn[d] = Math.min(mn[d], q[d]); mx[d] = Math.max(mx[d], q[d]); }
49	      }
50	      out.push({ node: n.name, mat: j.materials[p.material]?.name, tris: j.accessors[p.indices].count / 3, min: mn, max: mx, tex: j.materials[p.material]?.pbrMetallicRoughness?.baseColorTexture });
51	    }
52	  });
53	  return out;
54	}
55	const nodeByName = (j: any, name: string): { n: any; i: number } => { const i = j.nodes.findIndex((n: any) => n.name === name); assert.ok(i >= 0, `thiếu nút ${name}`); return { n: j.nodes[i], i }; };
56	/* Tâm bánh thế giới = gốc của nút (cha là vf3 có thể có biến đổi) */
57	function wheelCentre(j: any, name: string): Vec {
58	  const { i } = nodeByName(j, name);
59	  const parent = new Map<number, number>();
60	  j.nodes.forEach((n: any, k: number) => (n.children ?? []).forEach((c: number) => parent.set(c, k)));
61	  const world = (k: number): number[] => { const m = nodeMat(j.nodes[k]); return parent.has(k) ? mul(world(parent.get(k)!), m) : m; };
62	  return apply(world(i), [0, 0, 0]);
63	}
