65	test('vf3.glb tồn tại, ≤ 1,5 MB, ≤ 45 000 tam giác', () => {
66	  assert.ok(existsSync(FILE), 'thiếu public/car/vf3.glb (chạy npm run gen:car)');
67	  const n = statSync(FILE).size;
68	  assert.ok(n <= MAX_BYTES, `${n} byte > ${MAX_BYTES}`);
69	  const tris = worldBoxes(glbJson(FILE)).reduce((s, b) => s + b.tris, 0);
70	  assert.ok(tris <= MAX_TRIS, `${tris} tam giác > ${MAX_TRIS}`);
71	});
72	
73	test('có đủ nút vf3, body, wheel_fl, wheel_fr, wheel_rl, wheel_rr; bốn bánh đúng chỗ', () => {
