75	  for (const n of ['vf3', 'body', 'wheel_fl', 'wheel_fr', 'wheel_rl', 'wheel_rr']) nodeByName(j, n);
76	  const c = Object.fromEntries(['fl', 'fr', 'rl', 'rr'].map(k => [k, wheelCentre(j, 'wheel_' + k)]));
