78	  assert.ok(c.fl[0] > 0 && c.rl[0] < 0, 'bánh trước phải ở +X (mũi xe)');
79	  assert.ok(Math.abs(c.fl[2] + c.fr[2]) < 0.02 && Math.abs(c.rl[2] + c.rr[2]) < 0.02, 'không đối xứng qua Z');
80	  assert.ok(c.fl[2] < 0 && c.fr[2] > 0, 'bánh trái (fl) phải ở -Z (trái khi mũi +X, Y lên)');
81	  assert.ok(c.fl[0] - c.rl[0] > 0 && Math.abs(c.fl[2] - c.fr[2]) > 1.2 && Math.abs(c.fl[2] - c.fr[2]) < 1.9, 'vết bánh ngoài khoảng');
82	  const bs = worldBoxes(j).filter(b => b.node.startsWith('wheel_'));
83	  for (const b of bs) assert.ok(b.tris > 0, `${b.node} rỗng`);
84	  for (const k of ['fl', 'fr', 'rl', 'rr']) {
85	    const t = bs.filter(b => b.node === 'wheel_' + k).reduce((s, b) => s + b.tris, 0);
86	    const t0 = bs.filter(b => b.node === 'wheel_fl').reduce((s, b) => s + b.tris, 0);
87	    assert.equal(t, t0, `bánh ${k} khác số tam giác với bánh fl`);
88	  }
89	});
