91	test('có vật liệu paint, lamp_head, lamp_tail', () => {
92	  const names: string[] = glbJson(FILE).materials.map((m: any) => m.name);
93	  for (const n of ['paint', 'lamp_head', 'lamp_tail']) assert.ok(names.includes(n), `thiếu vật liệu ${n}: ${names}`);
