103	  assert.ok(mx[2] - mn[2] > 1.6 && mx[2] - mn[2] < 2.0, `rộng ${mx[2] - mn[2]}`);
104	  assert.ok(Math.abs(mx[0] + mn[0]) < 0.4, 'gốc lệch xa khỏi giữa xe');
105	});
